import type { SiteIdentity } from "../../lib/domain/contracts";
import { recordId } from "../../lib/domain/contracts";
import pdf from "../../lib/materials/pdf-wasm/validator.wasm";
import jpeg from "../../lib/materials/jpeg-wasm/decoder.wasm";
import { initializeOwnedUploadFixture } from "./material-transfer-setup";
import { uploadMaterialBody } from "../../lib/materials/upload";
import { completeMaterialTransfer } from "../../lib/materials/complete";
import { getMaterialTransfer } from "../../db/repositories/material-transfers";
import { saveExtractionSelection } from "../../db/repositories/extraction-jobs";
import { listExtractionPages, getExtractionPage, saveTextExtraction } from "../../db/repositories/extraction-pages";
import { confirmExtractionSegments } from "../../db/repositories/extraction-confirmations";
import { createExtractionSource } from "../../db/repositories/extraction-sources";
import { requireExtractionPage } from "../../lib/extraction/server";
import { materialFileReference } from "../../lib/materials/attachment";
import { buildSelection } from "../../lib/extraction/selection";
import { createMaterialLink, listConfirmedUnits } from "../../db/repositories/librarian-links";
import { createStudyScope, getStudyScope, beginStoredScopeEvaluation, saveScopeEvaluation, confirmStoredScope } from "../../db/repositories/study-scopes";
import { librarianOutputFixture } from "./librarian-output";
import { scopeInput } from "../../lib/librarian/contracts";
import { linkInput } from "../../lib/librarian/contracts";
import { confirmedPlanFixture } from "./confirmed-plan";
import type { PageResult } from "../../lib/extraction/result";
/** 격리된 로컬 D1·R2에 실제 저장 경로로 범위를 준비합니다. AI 응답만 모의 값입니다. */
const worker = { async fetch(request: Request, environment: Readonly<{ DB: D1Database; BUCKET: R2Bucket }>): Promise<Response> {
  const { DB, BUCKET } = environment;
  const owner: SiteIdentity = { realm: "sites", userId: "local_seedy" };
  const { id } = await initializeOwnedUploadFixture(DB, request, owner);
  const upload = await uploadMaterialBody(DB, BUCKET, owner, id, 1, request);
  await completeMaterialTransfer(DB, BUCKET, owner, id, upload.version, { pdf, jpeg }, new AbortController().signal);
  const transfer = await getMaterialTransfer(DB, owner, id);
  const units = await listConfirmedUnits(DB, owner); const unit = units.find((item): boolean => item.prerequisiteUnitIds.length === 0);
  if (!unit) throw new Error("로컬 확정 단원이 없어요.");
  const cmd = (expectedVersion: number) => ({ owner, requestKey: crypto.randomUUID(), expectedVersion });
  const selection = buildSelection(materialFileReference(transfer), "1", "");
  await saveExtractionSelection(DB, cmd(0), transfer, selection);
  const page = (await listExtractionPages(DB, owner, transfer.materialId, 1))[0];
  const proof = await requireExtractionPage(DB, BUCKET, owner, transfer.materialId, 1, 1);
  const text: string = "저자: ALTER. 출처: 자체 시험 자료. 판본: fixture-v1. 분수는 전체를 같은 크기로 나눈 부분입니다. 분모는 전체 조각 수, 분자는 선택한 조각 수입니다. 네 조각 중 하나는 1/4입니다. 연습: 같은 크기의 여덟 조각 중 세 조각을 분수로 써 보세요.";
  const result: PageResult = { filePage: 1, method: "text-layer", status: "complete", width: 612, height: 792, rotation: 0, segments: [{ id: "s0", kind: "text", text, bounds: { x: 0,y: 0,width: 1,height: 1 }, transform: null, uncertain: false, reason: null }], error: null, requiresConfirmation: true };
  await saveTextExtraction(DB, cmd(page.version), proof, page, result);
  const extracted = await getExtractionPage(DB, owner, page.id);
  if (!extracted.resultId) throw new Error("결과 누락");
  await confirmExtractionSegments(DB, cmd(extracted.version), proof, extracted, { selectionRevision: 1,filePage: 1,expectedVersion: extracted.version,resultId: extracted.resultId,segmentIds: ["s0"],printedPage: "i",comparedWithOriginal: true });
  const confirmed = await getExtractionPage(DB, owner, page.id);
  await createExtractionSource(DB, cmd(confirmed.version), proof, confirmed, "s0");
  const sourceId = await DB.prepare("SELECT source_id FROM extraction_sources WHERE owner_id=? AND result_id=?").bind(owner.userId, confirmed.resultId).first<string>("source_id"); if (!sourceId) throw new Error("출처 누락");
  const secondPlan = await confirmedPlanFixture(DB, owner);
  const secondUnit = (await listConfirmedUnits(DB, owner)).find(item=>item.planId===secondPlan.id && item.prerequisiteUnitIds.length===0);
  if(!secondUnit) throw new Error("두 번째 로컬 확정 단원이 없어요.");
  const scopeIds: string[]=[];
  for(const chosen of [unit,secondUnit]) {
  const input = linkInput.parse({ id: recordId.parse(crypto.randomUUID()), planVersionId: chosen.planVersionId, unitId: chosen.unitId, materialId: transfer.materialId, toc: "분수의 의미", sourceRefIds: [sourceId], bibliography: { author: "ALTER", origin: "자체 시험 자료", checked: true, evidenceSourceId: sourceId }, readingMinutes: 5 });
  await createMaterialLink(DB, BUCKET, cmd(1), input);
  const scopeValue = scopeInput.parse({ id: crypto.randomUUID(),planVersionId: chosen.planVersionId,unitId: chosen.unitId,date: "2026-10-25",availableMinutes: 30,questionMinutes: 5,practiceMinutes: 10,linkIds: [input.id] });
  await createStudyScope(DB, BUCKET, cmd(1), scopeValue);
  const start = await getStudyScope(DB, owner, scopeValue.id);
  await beginStoredScopeEvaluation(DB, BUCKET, cmd(start.version), scopeValue.id);
  const evaluating = await getStudyScope(DB, owner, scopeValue.id);
  await saveScopeEvaluation(DB, BUCKET, owner, evaluating, librarianOutputFixture(evaluating));
  const proposed = await getStudyScope(DB, owner, scopeValue.id);
  await confirmStoredScope(DB, BUCKET, cmd(proposed.version), proposed.input.id, { reviewedVersion: proposed.version, reviewedSources: true, acceptedTime: true, acceptedAssessment: true });
  scopeIds.push(scopeValue.id);
  }
  return Response.json({ status: "prepared", scopeIds, actualAiCalls: 0 });
} };
export default worker;
